// Vaste referentiefotos van Gerda (base64, server-only) voor beeldgeneratie.
export const GERDA_REF_1_B64 = "";
export const GERDA_REF_2_B64 = "";
export const GERDA_REF_INLINE = [
  { mimeType: "image/jpeg", data: GERDA_REF_1_B64 },
  { mimeType: "image/jpeg", data: GERDA_REF_2_B64 },
];
export const GERDA_REF_DATA_URLS = GERDA_REF_INLINE.map((r) => `data:${r.mimeType};base64,${r.data}`);
